import './helpers/hermetic-env.mjs';
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { applyCssOrigins, isGeneratedCss } from '../src/tracer/css-origin.js';

const FILES = {
  'src/styles/base/synced.css': '/* Synced from the platform - do not edit manually */\n.c-link u {\n  padding: 0;\n  min-height: 0;\n}\n',
  'src/styles/base/reset.css': 'a { margin: 0; width: auto; }\n',
  'src/styles/components/footer.css': '.c-link u {\n  display: inline-block;\n}\n\n.c-link__item a {\n  height: 14px;\n}\n',
  'src/styles/home-spacing.css': '.c-link-x {\n  padding: 1px;\n}\n',
  'src/partials/index/combo.liquid': '<div class="swiper-pagination-bullet-active">\n</div>\n<script>\n  var b = el.querySelectorAll(".x");\n  b.classList.add("swiper-pagination-bullet-active");\n</script>\n',
  'src/scripts/combo.js': 'el.setAttribute("aria-label", label);\n',
};
async function withSite(fn) {
  const root = mkdtempSync(join(tmpdir(), 'ada-cssorigin-'));
  try {
    for (const [rel, body] of Object.entries(FILES)) { mkdirSync(dirname(join(root, rel)), { recursive: true }); writeFileSync(join(root, rel), body); }
    return await fn(root);
  } finally { rmSync(root, { recursive: true, force: true }); }
}
const markup = { file: 'src/partials/layout/footer.liquid', line: 17, confidence: 'medium', method: 'source-hint-search' };
const finding = (cssRule, extra = {}) => ({ ruleId: 'target-size', cssRule, element: { outerHTML: '<u class="x">t</u>' }, source: { ...markup }, ...extra });
const rule = (cands, external = false) => ({ ...cands[0], external, candidates: cands.map((c) => ({ external: false, ...c })) });

test('generated or synced CSS is recognised by path and by header', async () => {
  await withSite(async (root) => {
    assert.equal(isGeneratedCss(root, 'src/styles/base/synced.css'), true);
    assert.equal(isGeneratedCss(root, 'src/styles/base/reset.css'), true);
    assert.equal(isGeneratedCss(root, 'src/styles/components/footer.css'), false);
    writeFileSync(join(root, 'src/styles/base/x.css'), '/* @generated by tool */\n.a { width: 1px; }\n');
    assert.equal(isGeneratedCss(root, 'src/styles/base/x.css'), true, 'header alone');
  });
});

test('size finding: the cascade winner is a synced reset; the authored rule that declares the size gets the finding, other authored rules are candidates', async () => {
  await withSite(async (root) => {
    const v = finding(rule([
      { selectorText: '.c-link u', props: ['padding', 'min-height'] }, // winner by cascade: the reset-like synced file
      { selectorText: '.c-link__item a', props: ['height'] },
    ]));
    applyCssOrigins([v], root);
    assert.deepEqual([v.source.file, v.source.line, v.source.method], ['src/styles/components/footer.css', 5, 'css-rule']);
    assert.deepEqual([v.source.markupFile, v.source.markupLine], [markup.file, 17]);
  });
});

test('several authored rules contribute: the most specific (first in cascade) is chosen, the rest are listed', async () => {
  await withSite(async (root) => {
    const v = finding(rule([{ selectorText: '.c-link-x', props: ['padding'] }, { selectorText: '.c-link__item a', props: ['height'] }, { selectorText: 'a', props: ['margin'], }]));
    applyCssOrigins([v], root);
    assert.deepEqual([v.source.file, v.source.line], ['src/styles/home-spacing.css', 1]);
    assert.deepEqual(v.sourceCandidates.map((c) => `${c.file}:${c.line}`), ['src/styles/components/footer.css:5']);
  });
});

test('only a generated rule declares the size: the finding stays on the markup, never on the do-not-edit file', async () => {
  await withSite(async (root) => {
    const v = finding(rule([{ selectorText: '.c-link u', props: ['padding'] }]));
    applyCssOrigins([v], root);
    assert.deepEqual([v.source.file, v.source.line, v.source.method], [markup.file, 17, 'source-hint-search']);
  });
});

test('a CSS-caused size finding is never left on a JavaScript line: inline <script> moves to the markup line, a .js file loses its line', async () => {
  await withSite(async (root) => {
    const inline = finding(null, { element: { outerHTML: '<span class="swiper-pagination-bullet-active"></span>' }, source: { file: 'src/partials/index/combo.liquid', line: 5, confidence: 'medium', method: 'source-hint-search' } });
    const js = finding(null, { source: { file: 'src/scripts/combo.js', line: 1, confidence: 'medium', method: 'source-hint-search' } });
    const colour = { ...finding(null), ruleId: 'color-contrast', source: { file: 'src/partials/index/combo.liquid', line: 5, confidence: 'medium', method: 'source-hint-search' } };
    applyCssOrigins([inline, js, colour], root);
    assert.deepEqual([inline.source.file, inline.source.line], ['src/partials/index/combo.liquid', 1]);
    assert.equal(js.source.line, null);
    assert.equal(colour.source.line, 5, 'other rules are not touched');
  });
});
